using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
namespace BluewaterHaul;
public sealed partial class SarniaGame {
 readonly Dictionary<(int,int),VertexPositionColorTexture[]> signMeshes=[];
 void BuildStreetSigns(){var chunks=new Dictionary<(int,int),List<VertexPositionColorTexture>>();foreach(var sign in StreetScene.Signs){var key=((int)MathF.Floor(sign.Point.X/128),(int)MathF.Floor(sign.Point.Y/128));if(!chunks.TryGetValue(key,out var data))chunks[key]=data=[];var dir=sign.Direction;var normal=new Vector2(-dir.Y,dir.X);float height=sign.Kind=="park"?.85f:.65f;var center=Geo.V3(sign.Point,sign.Height);float width=sign.Width;void Quad(Vector3 a,Vector3 b,Vector3 c,Vector3 d,Color color,Vector2 ta,Vector2 tb,Vector2 tc,Vector2 td){data.AddRange([new(a,color,ta),new(b,color,tb),new(c,color,tc),new(a,color,ta),new(c,color,tc),new(d,color,td)]);}
  // Atlas has a blank space glyph: use its transparent texel for board? Boards are
  // a separate opaque geometry pass below; glyphs remain depth-tested world objects.
  for(int side=-1;side<=1;side+=2){var u=Geo.V3(dir*side,0);var n=Geo.V3(normal*side,.0f)*.012f;string text=sign.Text.ToUpperInvariant();float advance=Math.Min(.23f,(width-.12f)/Math.Max(1,text.Length));float glyphH=Math.Min(height*.65f,advance*1.8f);var origin=center-u*(text.Length*advance/2)+n+new Vector3(0,glyphH/2,0);for(int i=0;i<text.Length;i++){char c=text[i];if(c<32||c>126)c='?';int index=c-32;float x=index%16*12/192f,y=index/16*20/120f;var a=origin+u*i*advance;var b=a+u*advance*1.2f;var down=new Vector3(0,-glyphH,0);Quad(a,b,b+down,a+down,sign.Kind=="street"?Color.White:new(240,223,168),new(x,y),new(x+12/192f,y),new(x+12/192f,y+20/120f),new(x,y+20/120f));}}
 }foreach(var(k,v)in chunks)signMeshes[k]=v.ToArray();}
 void DrawStreetSigns(){var boards=new MeshBuilder();foreach(var sign in StreetScene.Signs){if(Vector2.DistanceSquared(position,sign.Point)>280*280)continue;float height=sign.Kind=="park"?.85f:.65f;var u=sign.Direction*sign.Width/2;boards.Quad(Geo.V3(sign.Point-u,sign.Height-height/2),Geo.V3(sign.Point+u,sign.Height-height/2),Geo.V3(sign.Point+u,sign.Height+height/2),Geo.V3(sign.Point-u,sign.Height+height/2),sign.Color);}DrawMesh(boards);
  GraphicsDevice.BlendState=BlendState.AlphaBlend;GraphicsDevice.SamplerStates[0]=SamplerState.PointClamp;effect.TextureEnabled=true;effect.Texture=font;foreach(var(k,data)in signMeshes){var center=new Vector2(k.Item1*128+64,k.Item2*128+64);if(Vector2.DistanceSquared(position,center)>380*380)continue;foreach(var pass in effect.CurrentTechnique.Passes){pass.Apply();GraphicsDevice.DrawUserPrimitives(PrimitiveType.TriangleList,data,0,data.Length/3);}}effect.TextureEnabled=false;effect.Texture=null;GraphicsDevice.BlendState=BlendState.Opaque;
 }
 float GroundHeight(Vector2 p){float best=100;float height=0;foreach(var r in world.Roads.Where(r=>r.Bridge))for(int i=1;i<r.Points.Count;i++){var q=Geo.Nearest(p,Geo.V(r.Points[i-1]),Geo.V(r.Points[i]));float d=Vector2.DistanceSquared(p,q);if(d<best&&d<r.Width*r.Width/4){best=d;float fallback=Math.Max(.5f,float.TryParse(r.Layer,out var layer)?layer*3:3);height=StreetScene.Deck(r,q,fallback);}}return height;}
 int tourIndex;
 void TourNext(){var names=new[]{"Sarnia City Hall","Sarnia Library","Lawrence House","Blue Water Bridge","Golden Hawk Memorial","Canatara Park","Lambton College"};TourPlace(names[tourIndex++%names.Length]);}
 void TourPlace(string name){if(Trouble.Heat>0){Tell("Landmark tour unavailable during a police search.");return;}if(interior!=0)Leave();var destination=destinations.First(d=>d.Name==name);var target=destination.Point;var b=world.Buildings.FirstOrDefault(b=>b.Landmark==(name switch{"Sarnia City Hall"=>"cityhall","Sarnia Library"=>"library","Lawrence House"=>"lawrence","Lambton College"=>"college",_=>"!"}));position=FindRoad(target);if(b!=null){var f=Architecture.Front(b);var q=b.Door+f.Normal*(name=="Lawrence House"?24:30);if(!Blocked(q))position=q;target=Geo.V(b.Center);}if(name=="Blue Water Bridge"){position=FindRoad(new(-5940,-1580));target=new(-6260,-1790);}if(name=="Golden Hawk Memorial"){position=target+new Vector2(14,-20);if(Blocked(position))position=FindRoad(target);}truck=FindRoad(position+new Vector2(40,40));returnPosition=position;driving=false;activeVehicle=0;SynchronizeTruck();cameraReady=false;speed=0;map=journal=help=dialog=searchFocus=false;yaw=MathF.Atan2(-(target-position).X,-(target-position).Y);pitch=name=="Blue Water Bridge"?.16f:name=="Lawrence House"?.12f:0;SetWaypoint(b!=null?b.Door:destination.Point,name);UpdateRoad();Tell("Landmark tour: "+name+" / M then F6 for next stop");}

}
